class Solution {
    unordered_map<int, int> memo;
    int helper(int n) {
        if (n <= 1) return n;
        auto it = memo.find(n);
        if (it != memo.end()) return it->second;
        int res = 1 + min((n % 2) + helper(n / 2), (n % 3) + helper(n / 3));
        memo[n] = res;
        return res;
    }
public:
    int minDays(int n) {
        return helper(n);
    }
};
